<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { taskQueueApi } from '@/api'

const overview = ref({ queues: [], workers: [], schedules: [] })
const tasks = ref([]), total = ref(0), page = ref(1), pageSize = ref(50), totalPages = ref(1)
const pageSizes = [25, 50, 100, 200]
const selectedTaskId = ref(null), selectedTask = ref(null), loading = ref(false), loadingDetailFor = ref(null), error = ref('')
const filters = ref({ queue: '', status: '', task_key: '', correlation_id: '' })
let timer = null, filterTimer = null, refreshRequest = 0
const taskStatuses = ['pending', 'claimed', 'running', 'retrying', 'succeeded', 'failed', 'cancelled']
const queueNames = computed(() => overview.value.queues.map(queue => queue.name))
const activeWork = computed(() => overview.value.queues.reduce((sum, queue) => sum + (queue.counts.pending || 0) + (queue.counts.claimed || 0) + (queue.counts.running || 0) + (queue.counts.retrying || 0), 0))
const failedWork = computed(() => overview.value.queues.reduce((sum, queue) => sum + (queue.counts.failed || 0), 0))

function requestParams() { return { ...Object.fromEntries(Object.entries(filters.value).filter(([, value]) => value)), page: page.value, page_size: pageSize.value } }
async function refresh(showLoading = false) {
  if (showLoading) loading.value = true
  error.value = ''
  const requestId = ++refreshRequest
  try {
    const [overviewResponse, tasksResponse] = await Promise.all([taskQueueApi.overview(), taskQueueApi.tasks(requestParams())])
    if (requestId !== refreshRequest) return
    overview.value = overviewResponse.data; tasks.value = tasksResponse.data.results; total.value = tasksResponse.data.count; totalPages.value = tasksResponse.data.total_pages
    if (selectedTaskId.value && !tasks.value.some(task => task.id === selectedTaskId.value)) { selectedTaskId.value = null; selectedTask.value = null }
  } catch (requestError) { error.value = requestError.response?.data?.detail || 'Unable to load task operations data.' } finally { if (requestId === refreshRequest) loading.value = false }
}
async function selectTask(task) {
  if (selectedTaskId.value === task.id) { selectedTaskId.value = null; selectedTask.value = null; return }
  selectedTaskId.value = task.id; selectedTask.value = null; loadingDetailFor.value = task.id
  try { const { data } = await taskQueueApi.task(task.id); if (selectedTaskId.value === task.id) selectedTask.value = data } catch (requestError) { error.value = requestError.response?.data?.detail || `Unable to load task ${task.id}.` } finally { if (loadingDetailFor.value === task.id) loadingDetailFor.value = null }
}
function changePage(next) { if (next >= 1 && next <= totalPages.value && next !== page.value) { page.value = next; refresh() } }
function changePageSize() { page.value = 1; refresh() }
function formatDate(value) { return value ? new Date(value).toLocaleString() : '-' }
function age(value) { if (!value) return '-'; const seconds = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 1000)); if (seconds < 60) return `${seconds}s`; if (seconds < 3600) return `${Math.floor(seconds / 60)}m`; if (seconds < 86400) return `${Math.floor(seconds / 3600)}h`; return `${Math.floor(seconds / 86400)}d` }
function duration(task) { if (!task.started_at) return '-'; const seconds = Math.max(0, Math.round((new Date(task.finished_at || new Date()) - new Date(task.started_at)) / 1000)); return seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}m ${seconds % 60}s` }
function statusClass(status) { return `status status-${status}` }
function taskSummary(task) { if (task.last_error) return task.last_error; if (task.status === 'succeeded') return 'Completed successfully.'; if (task.status === 'retrying') return `Retry ${task.attempts} of ${task.max_attempts} waiting until ${formatDate(task.available_at)}.`; if (task.status === 'running') return 'Handler is executing.'; if (task.status === 'claimed') return `Claimed by ${task.locked_by || 'worker'}.`; return 'Waiting for a worker.' }
watch(filters, () => { clearTimeout(filterTimer); filterTimer = setTimeout(() => { page.value = 1; refresh() }, 250) }, { deep: true })
onMounted(() => { refresh(true); timer = setInterval(() => refresh(), 5000) })
onUnmounted(() => { clearInterval(timer); clearTimeout(filterTimer) })
</script>

<template>
  <main class="task-operations-view">
    <header class="operations-head"><div><p class="eyebrow">Durable Execution</p><h1>Task Operations</h1><p class="subtitle">Live queue, worker, scheduler, and execution feedback. Refreshes every 5 seconds.</p></div><button class="refresh-button" :disabled="loading" @click="refresh(true)">{{ loading ? 'Refreshing...' : 'Refresh now' }}</button></header>
    <p v-if="error" class="error-banner">{{ error }}</p>
    <section class="headline-metrics"><article class="metric-card"><span>Active work</span><strong>{{ activeWork }}</strong><small>pending, claimed, running, retrying</small></article><article class="metric-card failed"><span>Failed tasks</span><strong>{{ failedWork }}</strong><small>requires review or manual retry</small></article><article class="metric-card worker"><span>Live workers</span><strong>{{ overview.workers.length }}</strong><small>currently running</small></article><article class="metric-card schedule"><span>Active schedules</span><strong>{{ overview.schedules.filter(schedule => schedule.is_active).length }}</strong><small>scheduler only enqueues work</small></article></section>
    <section class="queue-grid"><article v-for="queue in overview.queues" :key="queue.name" class="queue-card"><div class="queue-title"><h2>{{ queue.display_name }}</h2><span>{{ queue.is_enabled && !queue.is_paused ? 'Ready' : queue.is_paused ? 'Paused' : 'Disabled' }}</span></div><div class="queue-counts"><span><b>{{ queue.counts.pending || 0 }}</b> pending</span><span><b>{{ queue.counts.running || 0 }}</b> running</span><span><b>{{ queue.counts.retrying || 0 }}</b> retrying</span><span><b>{{ queue.counts.failed || 0 }}</b> failed</span></div></article></section>
    <section class="operations-split"><article class="operations-panel"><div class="panel-title"><div><p class="eyebrow">Worker Registry</p><h2>Workers</h2></div><span>{{ overview.workers.length }}</span></div><div v-if="!overview.workers.length" class="empty-state">No running task workers.</div><div v-for="worker in overview.workers" :key="worker.worker_id" class="worker-row"><span :class="statusClass(worker.status)">{{ worker.status }}</span><div><strong>{{ worker.worker_id }}</strong><small>{{ worker.hostname }} &middot; PID {{ worker.process_id }}</small></div><div class="worker-meta"><small>{{ worker.queue_names.join(', ') }}</small><small>Heartbeat {{ age(worker.last_heartbeat_at) }} ago</small></div></div></article><article class="operations-panel"><div class="panel-title"><div><p class="eyebrow">Task Scheduler</p><h2>Schedules</h2></div><span>{{ overview.schedules.length }}</span></div><div v-if="!overview.schedules.length" class="empty-state">No schedules configured.</div><div v-for="schedule in overview.schedules" :key="schedule.id" class="schedule-row"><div><strong>{{ schedule.name }}</strong><small>{{ schedule.task_key }} &middot; {{ schedule.queue_name }}</small></div><small>Next {{ formatDate(schedule.next_run_at) }}</small></div></article></section>
    <section class="task-panel"><div class="task-panel-head"><div><p class="eyebrow">Execution Ledger</p><h2>Background Tasks <span>{{ total }}</span></h2></div><div class="task-filters"><select v-model="filters.queue"><option value="">All queues</option><option v-for="queue in queueNames" :key="queue" :value="queue">{{ queue }}</option></select><select v-model="filters.status"><option value="">All statuses</option><option v-for="status in taskStatuses" :key="status" :value="status">{{ status }}</option></select><input v-model.trim="filters.task_key" placeholder="Task key"><input v-model.trim="filters.correlation_id" placeholder="Correlation ID"></div></div><div class="task-table-wrap"><table class="task-table"><thead><tr><th>Task</th><th>Queue</th><th>State</th><th>Attempts</th><th>Correlation ID</th><th>Worker / timing</th><th>Feedback</th></tr></thead><tbody><tr v-if="!tasks.length"><td colspan="7" class="empty-cell">No tasks match the selected filters.</td></tr><template v-for="task in tasks" :key="task.id"><tr :class="{ selected: selectedTaskId === task.id }" @click="selectTask(task)"><td><strong>#{{ task.id }}</strong><span>{{ task.task_key }}</span><small>{{ age(task.created_at) }} ago &middot; {{ task.company_name || 'system' }}</small></td><td>{{ task.queue_name }}</td><td><span :class="statusClass(task.status)">{{ task.status }}</span></td><td>{{ task.attempts }} / {{ task.max_attempts }}</td><td class="correlation-cell">{{ task.correlation_id || '-' }}</td><td>{{ task.locked_by || '-' }}<small>{{ duration(task) }}</small></td><td class="feedback-cell">{{ taskSummary(task) }}</td></tr><tr v-if="selectedTaskId === task.id" class="detail-row"><td colspan="7"><p v-if="loadingDetailFor === task.id">Loading task events...</p><div v-else-if="selectedTask" class="detail-grid"><div><span :class="statusClass(selectedTask.status)">{{ selectedTask.status }}</span><p>{{ taskSummary(selectedTask) }}</p><dl><dt>Correlation</dt><dd>{{ selectedTask.correlation_id || '-' }}</dd><dt>Idempotency</dt><dd>{{ selectedTask.idempotency_key || '-' }}</dd><dt>Available</dt><dd>{{ formatDate(selectedTask.available_at) }}</dd></dl></div><div><h3>Task Event Log</h3><div v-for="event in selectedTask.events" :key="event.id" class="event"><strong>{{ event.event_type.replaceAll('_', ' ') }}</strong><small>{{ formatDate(event.created_at) }} &middot; attempt {{ event.attempt_number }}</small><p v-if="event.message">{{ event.message }}</p><pre v-if="event.error">{{ event.error }}</pre></div></div><details><summary>Payload and result</summary><div class="payload"><pre>{{ JSON.stringify(selectedTask.payload, null, 2) }}</pre><pre>{{ JSON.stringify(selectedTask.result, null, 2) }}</pre></div></details></div></td></tr></template></tbody></table></div><footer class="task-pagination"><span>Showing {{ tasks.length ? ((page - 1) * pageSize) + 1 : 0 }}-{{ Math.min(page * pageSize, total) }} of {{ total }}</span><label>Rows <select v-model.number="pageSize" @change="changePageSize"><option v-for="size in pageSizes" :key="size" :value="size">{{ size }}</option></select></label><div><button :disabled="page === 1" @click="changePage(page - 1)">Previous</button><span> Page {{ page }} of {{ totalPages }} </span><button :disabled="page === totalPages" @click="changePage(page + 1)">Next</button></div></footer></section>
  </main>
</template>

<style scoped>
.task-operations-view{height:100%;box-sizing:border-box;overflow:auto;padding:30px;background:radial-gradient(circle at 90% 0,#e2f8ed,transparent 28rem),#f6f7f4;color:#18231e}.operations-head,.panel-title,.task-panel-head,.task-pagination,.queue-title{display:flex;justify-content:space-between;align-items:center;gap:18px}.eyebrow{margin:0 0 5px;color:#558568;text-transform:uppercase;letter-spacing:.12em;font-size:.68rem;font-weight:800}h1,h2,h3,p{margin-top:0}h1{margin-bottom:6px;font-size:2rem}h2{margin-bottom:0;font-size:1.05rem}.subtitle,small{color:#6a796f}.refresh-button,button{border:0;background:#175c3b;color:#fff;padding:9px 12px;border-radius:7px;font-weight:700;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}.error-banner{padding:11px;color:#8d2822;background:#ffe9e6}.headline-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:26px 0 14px}.metric-card,.queue-card,.operations-panel,.task-panel{background:#fff;border:1px solid #e0e6df;border-radius:12px;box-shadow:0 7px 20px #233a2b0d}.metric-card{padding:17px;border-top:4px solid #289161}.metric-card.failed{border-color:#da6257}.metric-card.worker{border-color:#4e81aa}.metric-card.schedule{border-color:#be8a34}.metric-card strong{display:block;font:700 1.8rem Georgia,serif;margin:5px 0}.queue-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.queue-card{padding:16px}.queue-title span{font-size:.7rem;color:#1b7d4b}.queue-counts{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px;font-size:.78rem}.operations-split{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}.operations-panel{padding:17px}.panel-title>span{background:#eaf2eb;padding:3px 8px;border-radius:99px}.worker-row,.schedule-row{display:grid;grid-template-columns:auto 1fr auto;gap:10px;padding:12px 0;border-top:1px solid #eef1ed}.worker-row strong,.schedule-row strong{display:block;word-break:break-all}.worker-meta{text-align:right}.empty-state,.empty-cell{color:#78847c;padding:20px 0}.task-panel-head{padding:18px;border-bottom:1px solid #e6ebe6}.task-filters{display:flex;flex-wrap:wrap;gap:7px}.task-filters input,.task-filters select,.task-pagination select{border:1px solid #d6ded7;padding:8px;border-radius:7px;background:#fafcf9}.task-table-wrap{overflow:auto}.task-table{width:100%;min-width:1120px;border-collapse:collapse;font-size:.75rem}.task-table th{text-align:left;padding:8px 12px;background:#f8faf7;color:#728076;text-transform:uppercase;font-size:.63rem}.task-table td{padding:9px 12px;border-top:1px solid #edf0ec;vertical-align:top}.task-table tbody tr{cursor:pointer}.task-table tbody tr:hover,.task-table tr.selected{background:#f0f8f2}.task-table strong,.task-table td span{display:block}.correlation-cell{max-width:190px;word-break:break-all;color:#53675a}.feedback-cell{max-width:280px;color:#526258}.status{display:inline-block!important;border-radius:99px;padding:3px 8px;font-size:.66rem;font-weight:800;text-transform:uppercase}.status-pending,.status-retrying{background:#fff2cf;color:#8e6112}.status-claimed,.status-running{background:#dceefb;color:#21628f}.status-succeeded{background:#ddf3e4;color:#1b7240}.status-failed{background:#ffe1dd;color:#a72f28}.detail-row{cursor:default!important;background:#f7fbf8!important}.detail-grid{display:grid;grid-template-columns:minmax(220px,.7fr) 2fr;gap:22px;padding:8px 0}.detail-grid details{grid-column:1/-1}dl{display:grid;grid-template-columns:90px 1fr;gap:7px;font-size:.75rem}dd{margin:0;word-break:break-all}.event{padding:0 0 12px}.event strong,.event small{display:block}.event pre,pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7f4;padding:10px;border-radius:6px;font-size:.7rem}.payload{display:grid;grid-template-columns:1fr 1fr;gap:12px}.task-pagination{padding:10px 14px;border-top:1px solid #e6ebe6;font-size:.76rem}.task-pagination label{display:flex;align-items:center;gap:6px}@media(max-width:900px){.task-operations-view{padding:18px}.headline-metrics,.operations-split{grid-template-columns:1fr 1fr}.detail-grid{grid-template-columns:1fr}.operations-head,.task-panel-head,.task-pagination{align-items:flex-start;flex-direction:column}.payload{grid-template-columns:1fr}}@media(max-width:560px){.headline-metrics,.operations-split{grid-template-columns:1fr}}
</style>
